export default{props:{ranking:Object,userId:Number,busy:Boolean},data(){return{modes:['1v1','2v1','2v2'],mode:this.ranking?.mode||'1v1',search:''};},computed:{top(){return Array.from({length:3},(_,i)=>this.ranking?.mode===this.mode?this.ranking.top?.[i]||null:null);}},watch:{'ranking.mode'(mode){if(mode)this.mode=mode;this.resetScroll();},'ranking.page'(){this.resetScroll();}},methods:{resetScroll(){this.$nextTick(()=>{const node=this.$el.querySelector('.ranking-scroll');if(node)node.scrollTop=0;});},name:id=>`Pokémon n°${id}`,format:n=>Number(n).toLocaleString('fr-FR'),changeMode(mode){this.mode=mode;this.search='';this.load(1);},load(page){this.$emit('command','board',{mode:this.mode,page,search:this.search});}}};
